  1	/* ============================ Lái xe máy: điều phối chế độ (lái một mình, máy tính) ============================
  2	   Spec D-040. Cấu trúc theo explore/drive/index.ts; dùng lại các phần thuần của chế độ ô tô (mạng đường, va chạm, camera sau xe, HUD),
  3	   drive/* không bao giờ import ngược từ bike/*.
  4	   - Mạng đường DÙNG CHUNG với ô tô: drEnsureNet() của drive/index.ts (dựng một lần cho cả trang; drCollectRuntime chỉ push, dựng net thứ hai sẽ nhân đôi vật cản).
  5	   - Thân va chạm: start() đặt drUseBody(BK_BODY), stop() trả DR_CAR_BODY (drive.start() cũng tự đặt lại thân ô tô).
  6	   - Mỗi khung: phím → BkInput (keys.ts), grip = 1 (Task 7 nối thời tiết), bkStep với hộp xe tự động gần xe (trNearby), hình xe (model.ts),
  7	     camera (camera.ts): mặc định góc thứ nhất trên yên, V trộn sang góc thứ ba (drCamPlace với CONFIG.bike.cam3) trong cam1.mixS; fov / near đổi thì onResize();
  8	     mặt đồng hồ (dash.ts) vẽ lại ≤ dash.hz; controls.target theo xe (tâm vùng bóng đổ), HUD (đồng hồ + bản đồ nhỏ của ô tô), exNightStep(dt, false).
  9	   - Mắt góc thứ nhất: đo MỘT lần khi người lái thật gắn vào mô hình thật (riderEye: giữa hai xương mắt ở tư thế ngồi nền, hệ thân xe), không theo xương mỗi khung;
 10	     chưa có thì cam1.eye. Camera còn sát mắt (mix < cam1.headMix) thì ẩn đầu + mũ (rider.setFirstPerson). prefers-reduced-motion ⇒ cam1.motionReduced.
 11	   - Phím (theo e.code, chỉ khi đang lái, bỏ ô nhập và tổ hợp Ctrl / Meta / Alt; blur / ẩn tab nhả hết): R về làn (bkRecover), Q / E xi nhan trái / phải (bkSignal),
 12	     V đổi góc nhìn thứ nhất ↔ thứ ba, H còi (giữ; nhả khi blur / ẩn tab / focus vào ô nhập). Kéo chuột trái / vuốt trên canvas: nhìn quanh (thứ nhất) hoặc quay quanh xe (thứ ba).
 13	   - Lớp body 'explore drive bike': khung HUD #drHud và các quy tắc CSS của body.drive áp nguyên; 'bike' cho phần riêng về sau.
 14	   - Thoát: explore.exit() gọi bike.stop() rồi tải lại trang. Chưa có: nhiều người (Task 10), cảm ứng (Task 9). Mô hình thật: model.ts (làm nóng qua bkModelSetWarm bên dưới).
 15	   - Người lái: rider.ts, nhân vật theo stChar (chung Đi dạo), nạp ở preload() / start() (làm nóng qua stRigSetWarm của stroll/index.ts); chưa về thì xe không người,
 16	     về sau stop() thì bỏ. Người gắn vào neo yên của xe nên rời cảnh cùng model.group.
 17	   - Âm thanh (sound.ts bkSound): đề máy ở start(), tắt máy ở stop(); mỗi khung một BkSoundIn tái dùng (hộp xe gần dùng lại mảng trNearby của bkStep,
 18	     river từ |x| so với mép kè, tunnel từ ô mặt đường dưới xe, mưa = 0 trong hầm); nút 🔊 #drSoundBtn chung với ô tô, bkSound.bind chỉ toggle khi đang lái xe máy.
 19	   Mỗi khung không cấp phát (D-018). */
 20	import * as THREE from 'three';
 21	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
 22	import { composer, onResize } from '../../core/postprocessing';
 23	import { cam } from '../../views/state';
 24	import { CONFIG } from '../../config';
 25	import { driveView } from '../../environment/driveRoads';
 26	import { drSetGate, type DrNet } from '../drive/net';
 27	import { DR_GATE_SWING } from '../drive/roadData';
 28	import { drUseBody, DR_CAR_BODY, type DrBox } from '../drive/collide';
 29	import { drBindDrop } from '../drive/keys';
 30	import { drHudShow, drHudHide, drHudUpdate, type DrMapDot } from '../drive/hud';
 31	import { drEnsureNet } from '../drive';
 32	import { trNearby } from '../../common/trafficQuery';
 33	import { exNightStep } from '../nightShows';
 34	import { weatherU, shared } from '../../core/shared';
 35	import { bkCreate, bkStep, bkRecover, bkSignal, bkPitch, BK_BODY, type BkState, type BkInput } from './motion';
 36	import { bkInputFromKeys, BK_KEYS } from './keys';
 37	import { BkBike, bkModelLoad, bkModelSetWarm, type BkPlace } from './model';
 38	import { BkRider, bkRiderLoad, type BkRiderSig } from './rider';
 39	import { bkCamCreate, bkCamStep, bkCamPlace, bkCamDrag, bkCamSetEye, type BkCam } from './camera';
 40	import { BkDash } from './dash';
 41	import { bkSound, bkRiverK, type BkSoundIn } from './sound';
 42	import { stChar } from '../stroll/char';
 43	import type { SwingController } from '../../bridges/song-han/SwingController';
 44	
 45	/* Làm nóng shader của xe máy (D-018), như drive/index.ts drCarSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
 46	   đèn / sương / bóng lấy từ cảnh chính, camera chính. Nhóm làm nóng (mô hình, mặt đồng hồ, hình tạm, tấm bóng) do model.ts dựng, không thêm vào scene */
 47	bkModelSetWarm(async (o: THREE.Object3D) => {
 48	  const rt = renderer.getRenderTarget();
 49	  renderer.setRenderTarget(null);
 50	  const a = renderer.compileAsync(o, camera, scene);
 51	  renderer.setRenderTarget(rt);
 52	  await a;
 53	  renderer.setRenderTarget(composer.readBuffer);
 54	  const b = renderer.compileAsync(o, camera, scene);
 55	  renderer.setRenderTarget(rt);
 56	  await b;
 57	});
 58	
 59	const BK_SOLO_SLOT = -1;   // bkCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot (trên Cầu Rồng, đi Đông, bên phải)
 60	const C1 = CONFIG.bike.cam1;
 61	const NO_DOTS: DrMapDot[] = [];   // lái một mình: bản đồ nhỏ không có xe người khác
 62	
 63	let net: DrNet | null = null;
 64	let state: BkState | null = null;
 65	let ctrl: SwingController | null = null;
 66	let model: BkBike | null = null;   // hình xe của mình, dựng lần đầu vào chế độ
 67	let rider: BkRider | null = null;  // người lái có xương (rider.ts); null khi nhân vật chưa nạp / nạp lỗi: xe không người (không hình tạm cho người)
 68	let riderCh = -1;                  // nhân vật của rider hiện có (stChar)
 69	let riderGen = 0;                  // tăng ở mỗi start() / stop(): kết quả nạp về muộn của lần trước bị bỏ
 70	const _sig: BkRiderSig = { lean: 0, acc: 0, susF: 0, susR: 0, steer: 0 };   // tín hiệu người lái tái dùng mỗi khung
 71	const bkKeys = new Set<string>();   // e.code đang giữ
 72	const camB: BkCam = bkCamCreate();  // camera thứ nhất / thứ ba (camera.ts); view mặc định 1
 73	let dash: BkDash | null = null;     // mặt đồng hồ canvas, dựng lần đầu vào chế độ
 74	let motionK = C1.motion;            // hệ số chuyển động phụ: prefers-reduced-motion ⇒ motionReduced (đọc ở start())
 75	let eyeFor: BkRider | null = null;  // người lái đã đo mắt góc thứ nhất (riderEye)
 76	const _eye = new THREE.Vector3();
 77	const _rest: BkPlace = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, lean: 0, steer: 0, wheel: 0, susF: 0, susR: 0, braking: false, sig: 0 };
 78	const _sig0: BkRiderSig = { lean: 0, acc: 0, susF: 0, susR: 0, steer: 0 };
 79	const _inp: BkInput = { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 };   // đầu vào tái dùng mỗi khung
 80	const boxes: DrBox[] = [];          // hộp xe tự động gần xe, tái dùng mỗi khung
 81	let saved: { fov: number; near: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại
 82	const _snd: BkSoundIn = { v: 0, rpm: 0, throttle: 0, brakeK: 0, sus: 0, sig: 0, rain: 0, tunnel: false, river: 0, view: 1, near: boxes, nNear: 0, x: 0, z: 0, yaw: 0, t: 0 };   // đầu vào âm thanh tái dùng mỗi khung
 83	
 84	const active = () => cam.mode === 'bike' && state !== null;
 85	const inMode = () => active();     // chế độ xem (hết chỗ) ở Task 10
 86	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
 87	
 88	/* Một bước: cổng nhịp quay, chuyển động (sơ tán nằm trong bkStep), hình xe, camera, HUD, hiệu ứng đêm */
 89	function advance(dt: number, inp: BkInput): void {
 90	  const s = state!, n = net!;
 91	  if (ctrl) drSetGate(n, DR_GATE_SWING, ctrl.state !== 'CLOSED');
 92	  const nNear = trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes);
 93	  bkStep(s, inp, n, boxes, nNear, dt);
 94	  model!.place(s);
 95	  riderStep(s, dt);
 96	  riderEye();
 97	  bkCamStep(camB, s, dt, motionK);
 98	  if (bkCamPlace(camera, s, camB, n, dt)) onResize();   // fov / near đổi trong lúc trộn góc nhìn
 99	  rider?.setFirstPerson(camB.mix < C1.headMix);
100	  if (dash) { dash.bind(model!.dashMat); dash.update(dt, s.v, s.rpm, s.sig); }
101	  controls.target.set(s.x, s.y, s.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
102	  drHudUpdate(s, NO_DOTS);
103	  exNightStep(dt, false);
104	  soundStep(s, n, nNear);
105	}
106	
107	/* Âm thanh: điền BkSoundIn từ trạng thái xe (không cấp phát); bkSound tự giới hạn số lần ghi tham số (updateMs) */
108	function soundStep(s: BkState, n: DrNet, nNear: number): void {
109	  const tunnel = bkInTunnel(n, s);
110	  _snd.v = s.v; _snd.rpm = s.rpm; _snd.throttle = s.throttle; _snd.brakeK = s.brakeK; _snd.sig = s.sig;
111	  _snd.sus = Math.max(Math.abs(s.susF), Math.abs(s.susR));
112	  _snd.rain = tunnel ? 0 : weatherU.uRain.value; _snd.tunnel = tunnel; _snd.river = bkRiverK(s.x);
113	  _snd.view = camB.view; _snd.nNear = nNear; _snd.x = s.x; _snd.z = s.z; _snd.yaw = s.yaw; _snd.t = shared.uTime.value;
114	  bkSound.update(_snd);
115	}
116	
117	/* Xe đang ở ô hầm không: ô chứa (x, z) có cao độ gần y nhất trong ± stepMax (như drive/net.ts drPadAt), kiểu 'tunnel'. Duyệt tuyến tính, không cấp phát */
118	function bkInTunnel(n: DrNet, s: BkState): boolean {
119	  const step = CONFIG.drive.stepMax;
120	  let best = -1, bestD = Infinity;
121	  for (let i = 0; i < n.pads.length; i++) {
122	    const p = n.pads[i];
123	    if (s.x < p.x0 || s.x > p.x1 || s.z < p.z0 || s.z > p.z1 || (p.gate !== undefined && n.closed.has(p.gate))) continue;
124	    const d = Math.abs(p.y(s.x, s.z) - s.y);
125	    if (d <= step && d < bestD) { best = i; bestD = d; }
126	  }
127	  return best >= 0 && n.pads[best].kind === 'tunnel';
128	}
129	
130	/* Người lái theo xe (sau model.place): tín hiệu từ trạng thái chuyển động */
131	function riderStep(s: BkState, dt: number): void {
132	  if (!rider || !model) return;
133	  _sig.lean = s.lean; _sig.acc = s.acc; _sig.susF = s.susF; _sig.susR = s.susR; _sig.steer = s.steer;
134	  rider.update(model, _sig, dt);
135	}
136	
137	/* Mắt góc thứ nhất theo người lái: đo một lần khi có người lái thật trên mô hình thật. Đặt xe về tư thế nghỉ (thẳng đứng, không lái, giảm xóc 0),
138	   người lái tư thế ngồi nền (lò xo phản ứng chưa chạy với người mới), giữa hai xương mắt (+ cam1.eyeFore; không có thì xương đầu + cam1.headEye)
139	   → hệ thân xe (nhóm ngoài: yaw · dốc, dốc = 0); rồi đặt lại như cũ */
140	function riderEye(): void {
141	  const s = state, r = rider, m = model;
142	  if (!r || !m || !m.real) { if (eyeFor) { eyeFor = null; bkCamSetEye(null); } return; }
143	  if (eyeFor === r || !s) return;
144	  eyeFor = r;
145	  _rest.x = s.x; _rest.y = s.y; _rest.z = s.z; _rest.yaw = s.yaw;
146	  m.place(_rest);
147	  r.update(m, _sig0, 0);
148	  r.setFirstPerson(false);
149	  const eyes = r.eyeLocal(m.group, _eye);
150	  bkCamSetEye(eyes ? { fore: _eye.x + C1.eyeFore, up: _eye.y } : { fore: _eye.x + C1.headEye.fore, up: _eye.y + C1.headEye.up });
151	  m.place(s);
152	  riderStep(s, 0);
153	}
154	
155	/* Nạp người lái theo nhân vật đã chọn (stChar, chung với Đi dạo). Về sau stop() / start() khác thì bỏ; nhân vật đổi thì thay người cũ */
156	function riderNeed(): void {
157	  const ch = stChar.get(), gen = ++riderGen;
158	  if (rider && riderCh === ch) return;
159	  void bkRiderLoad(ch).then((src) => {
160	    if (gen !== riderGen || state === null || !src) return;
161	    try {
162	      const r = new BkRider(src);
163	      rider?.dispose(); rider = r; riderCh = ch;
164	      riderStep(state, 0);
165	    } catch (e) { console.warn('Lái xe máy: không dựng được người lái', e); }
166	  });
167	}
168	
169	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
170	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
171	  if (!net || !model) return;
172	  const s = bkCreate(net, BK_SOLO_SLOT);
173	  let gy = -Infinity;
174	  for (const p of net.pads) {
175	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
176	    gy = Math.max(gy, p.y(x, z));
177	  }
178	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
179	  bkPitch(s, net);
180	  state = s;
181	  bkCamReset();
182	  model.place(s);
183	  riderStep(s, 0);
184	  riderEye();
185	  if (bkCamPlace(camera, s, camB, net, 0, true)) onResize();
186	  controls.target.set(s.x, s.y, s.z);
187	}
188	
189	/* Trạng thái camera về đầu (giữ góc nhìn đang chọn, trộn xong ngay) */
190	function bkCamReset(): void {
191	  const v = camB.view;
192	  Object.assign(camB, bkCamCreate());
193	  camB.view = v; camB.mix = v === 3 ? 1 : 0;
194	}
195	
196	export const bike = {
197	  active,
198	  inMode,
199	  get state(): BkState | null { return state; },
200	  get net(): DrNet | null { return net; },
201	  get model(): BkBike | null { return model; },   // hình xe của mình (test: real, anchors)
202	  get rider(): BkRider | null { return rider; },  // người lái (test: debug(), setFirstPerson)
203	  get view(): 1 | 3 { return camB.view; },
204	  get cam(): BkCam { return camB; },               // test: mix, roll, bob, surge, yaw / pitch nhìn quanh
205	  get dash(): BkDash | null { return dash; },
206	  get cfg(): typeof CONFIG.bike { return CONFIG.bike; },   // test / kiểm tay: chỉnh số camera lúc chạy
207	  get sound(): typeof bkSound { return bkSound; },        // test: nodes(), on, graph
208	  /* Đổi góc nhìn: trộn vị trí + hướng + fov + near trong cam1.mixS, không dừng xe */
209	  setView(v: 1 | 3): void { camB.view = v === 3 ? 3 : 1; },
210	  /* Vào lái một mình */
211	  start(): void {
212	    drUseBody(BK_BODY);
213	    const n = drEnsureNet();
214	    net = n;
215	    state = bkCreate(n, BK_SOLO_SLOT);
216	    camB.view = 1; bkCamReset();
217	    motionK = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches ? C1.motionReduced : C1.motion;
218	    if (!model) model = new BkBike();
219	    if (!dash) dash = new BkDash();
220	    scene.add(model.group);
221	    model.place(state);
222	    riderNeed();
223	    riderStep(state, 0);
224	    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
225	    bkKeys.clear();
226	    drHudShow(n); bkSound.start();
227	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
228	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
229	    riderEye();
230	    bkCamPlace(camera, state, camB, n, 0, true); onResize();   // fov / near góc thứ nhất; onResize cập nhật ma trận chiếu và hệ số cỡ điểm
231	    controls.target.set(state.x, state.y, state.z);
232	    document.body.classList.add('explore', 'drive', 'bike');
233	  },
234	  update(dt: number): void {
235	    if (!active()) return;
236	    bkInputFromKeys(bkKeys, _inp);
237	    bkSound.horn(bkKeys.has('KeyH'));
238	    _inp.grip = 1;                            // Task 7: theo thời tiết (weatherU.uWet), khô trong hầm kín
239	    advance(dt, _inp);
240	  },
241	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
242	  afterRender(): void { /* chưa có việc */ },
243	  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
244	  stop(): void {
245	    if (state === null) return;
246	    state = null; bkKeys.clear(); riderGen++;
247	    bkSound.stop();
248	    rider?.setFirstPerson(false);
249	    drHudHide();
250	    model?.group.removeFromParent();
251	    driveView.far = 1;
252	    drUseBody(DR_CAR_BODY);
253	    document.body.classList.remove('drive', 'bike');
254	    if (saved) {
255	      if (!saved.explore) document.body.classList.remove('explore');
256	      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
257	      saved = null;
258	    }
259	    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
260	  },
261	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
262	  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
263	  placeAt: bkPlaceAt,
264	  /* Nạp mô hình thật (scooter.glb) và nhân vật người lái sớm, khi chọn thẻ Xe máy */
265	  preload(): void { void bkModelLoad(); void bkRiderLoad(stChar.get()); }
266	};
267	
268	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem (Task 10) */
269	export function setupBike(c: SwingController, onExit: () => void): void {
270	  ctrl = c; void onExit;
271	  window.addEventListener('keydown', (e) => {
272	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
273	    if (e.ctrlKey || e.metaKey || e.altKey) return;
274	    if (isField(e.target)) return;
275	    if (!BK_KEYS.has(e.code)) return;
276	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
277	    bkKeys.add(e.code);
278	    if (e.repeat) return;
279	    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
280	    if (e.code === 'KeyR') bkRecover(state!, net!);
281	    else if (e.code === 'KeyQ') bkSignal(state!, 1);
