253	    document.body.classList.remove('drive', 'bike');
254	    if (saved) {
255	      if (!saved.explore) document.body.classList.remove('explore');
256	      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
257	      saved = null;
258	    }
259	    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
260	  },
261	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
262	  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
263	  placeAt: bkPlaceAt,
264	  /* Nạp mô hình thật (scooter.glb) và nhân vật người lái sớm, khi chọn thẻ Xe máy */
265	  preload(): void { void bkModelLoad(); void bkRiderLoad(stChar.get()); }
266	};
267	
268	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem (Task 10) */
269	export function setupBike(c: SwingController, onExit: () => void): void {
270	  ctrl = c; void onExit;
271	  window.addEventListener('keydown', (e) => {
272	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
273	    if (e.ctrlKey || e.metaKey || e.altKey) return;
274	    if (isField(e.target)) return;
275	    if (!BK_KEYS.has(e.code)) return;
276	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
277	    bkKeys.add(e.code);
278	    if (e.repeat) return;
279	    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
280	    if (e.code === 'KeyR') bkRecover(state!, net!);
281	    else if (e.code === 'KeyQ') bkSignal(state!, 1);
282	    else if (e.code === 'KeyE') bkSignal(state!, -1);
283	    else if (e.code === 'KeyV') bike.setView(camB.view === 3 ? 1 : 3);
284	  });
285	  window.addEventListener('keyup', (e) => {
286	    bkKeys.delete(e.code);
287	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
288	  });
289	  const drop = drBindDrop(window, document, bkKeys);
290	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); bkSound.horn(false); } });
291	  window.addEventListener('blur', () => bkSound.horn(false));
292	  document.addEventListener('visibilitychange', () => { if (document.hidden) bkSound.horn(false); });
293	  bkSound.bind(document.getElementById('drSoundBtn'));   // nút 🔊 / 🔇 chung với ô tô: chỉ toggle tiếng xe máy khi đang lái xe máy
294	  /* Kéo chuột trái / vuốt (một ngón) trên canvas: nhìn quanh (góc thứ nhất) hoặc quay quanh xe (góc thứ ba) */
295	  let dragId = -1, lx = 0, ly = 0;
296	  canvas.addEventListener('pointerdown', (e) => {
297	    if (!active() || e.button !== 0 || dragId !== -1) return;
298	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
299	    canvas.setPointerCapture(e.pointerId);
300	  });
301	  canvas.addEventListener('pointermove', (e) => {
302	    if (e.pointerId !== dragId) return;
303	    bkCamDrag(camB, e.clientX - lx, e.clientY - ly);
304	    lx = e.clientX; ly = e.clientY;
305	  });
306	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
307	  canvas.addEventListener('pointerup', end);
308	  canvas.addEventListener('pointercancel', end);
309	  canvas.addEventListener('lostpointercapture', end);
310	}

