     1	/* ============================ Lái xe máy: camera góc thứ nhất + trộn với góc thứ ba ============================
     2	   Spec D-040 §7, §17.5.
     3	   - Mắt: một điểm cố định trong hệ thân xe (tâm giữa hai vệt bánh trên mặt đường, mũi +X), không lấy từ xương đầu mỗi khung (tránh rung theo hoạt ảnh).
     4	     index.ts đo một lần khi người lái gắn vào xe (xương đầu ở tư thế ngồi nền + cam1.headEye) rồi gọi bkCamSetEye; chưa có người lái thật thì cam1.eye.
     5	   - Vị trí mắt theo đủ chuyển động thân xe: góc chúi + nhún do giảm xóc, cuộn lean quanh đường chạm đất, dốc pitch, yaw (như model.ts place()),
     6	     cộng dồn (surge, dọc xe) và nhún (bob, đứng). Hướng nhìn thì đầu người giữ thăng bằng: cuộn = lò xo tới rollK · lean, chúi = pitchK · góc chúi giảm xóc,
     7	     cộng dốc, cúi sẵn cam1.tilt và góc nhìn quanh do kéo chuột (yaw / pitch, kẹp, thôi kéo returnAfter giây thì tự về).
     8	   - Lò xo cuộn / nhún / dồn: bậc hai, Euler ẩn, bước con ≤ 1/120 s, dt kẹp cam1.dtMax; nhún và dồn nhân `motion` (prefers-reduced-motion ⇒ motionReduced,
     9	     index.ts chọn), motion = 0 thì tắt hẳn; cuộn giữ (đường chân trời nghiêng là thông tin lái, không phải rung).
    10	   - Đổi góc nhìn: c.view là đích, c.mix đi tuyến tính 0 (thứ nhất) ↔ 1 (thứ ba) trong mixS giây; vị trí + hướng trộn theo smoothstep(mix).
    11	     Góc thứ ba = drCamPlace với CONFIG.bike.cam3, gọi mỗi khung cả khi đang ở góc thứ nhất (trạng thái trễ của nó luôn sẵn: bấm V không giật),
    12	     cuộn thêm c.roll (đích roll3K · lean khi mix = 1). Góc thứ ba có DrCam riêng (c3) cho kéo chuột quay quanh xe; một lúc chỉ một xe máy của mình.
    13	   - fov / near nội suy theo mix (cam1 ↔ cam3); bkCamPlace trả true khi một trong hai đổi để người gọi chạy onResize() (ma trận chiếu).
    14	   Không cấp phát mỗi khung (D-018). */
    15	import * as THREE from 'three';
    16	import { CONFIG } from '../../config';
    17	import { drCamPlace, drCamDrag, type DrCam } from '../drive/camera';
    18	import type { DrNet } from '../drive/net';
    19	import type { BkState } from './motion';
    20	
    21	export interface BkCam { view: 1 | 3; mix: number; yaw: number; pitch: number; idle: number; roll: number; rollV: number; bob: number; bobV: number; surge: number; surgeV: number }   // view đích; mix 0 thứ nhất .. 1 thứ ba; yaw / pitch rad nhìn quanh (trái + / lên +); idle s từ lần kéo cuối; roll rad (trái +), bob m (lên +), surge m (trước +) và vận tốc của chúng
    22	export interface BkEye { x: number; y: number; z: number; yaw: number; pitch: number; roll: number }   // m thế giới; yaw rad (quy ước xe: 0 mũi +X); pitch rad (lên +); roll rad (nghiêng trái +)
    23	
    24	const C1 = CONFIG.bike.cam1, K3 = CONFIG.bike.cam3, L = CONFIG.bike.body.wheelbase, LEAN_MAX = CONFIG.bike.perf.leanMax, HARD = CONFIG.bike.perf.hardBrake;
    25	const W = 2 * Math.PI * C1.hz;
    26	const fin = (v: number): number => (Number.isFinite(v) ? v : 0);
    27	const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v);
    28	
    29	/* Mắt trong hệ thân xe: đo từ người lái (bkCamSetEye) hoặc cam1.eye */
    30	const eyeAt = { fore: C1.eye.fore, up: C1.eye.up };
    31	export function bkCamSetEye(e: { fore: number; up: number } | null): void {
    32	  eyeAt.fore = e ? e.fore : C1.eye.fore; eyeAt.up = e ? e.up : C1.eye.up;
    33	}
    34	
    35	const c3: DrCam = { yaw: 0, pitch: 0, idle: 0 };   // góc nhìn quanh của góc thứ ba (drCamDrag)
    36	
    37	export function bkCamCreate(): BkCam {
    38	  c3.yaw = 0; c3.pitch = 0; c3.idle = 0;
    39	  return { view: 1, mix: 0, yaw: 0, pitch: 0, idle: 0, roll: 0, rollV: 0, bob: 0, bobV: 0, surge: 0, surgeV: 0 };
    40	}
    41	
    42	/* Thuần: tư thế mắt góc thứ nhất từ trạng thái xe + trạng thái camera (lò xo, nhìn quanh) */
    43	export function bkCamEye(s: BkState, c: BkCam, out: BkEye): void {
    44	  const susF = fin(s.susF), susR = fin(s.susR), lean = fin(s.lean), p = fin(s.pitch), yaw = fin(s.yaw);
    45	  const ex = eyeAt.fore - C1.back + fin(c.surge), ey = eyeAt.up;
    46	  /* phần trên lò xo: chúi φ (đầu xuống khi giảm xóc trước nén hơn sau), nhún xuống theo độ lún trung bình */
    47	  const phi = (susR - susF) / L, cp = Math.cos(phi), sp = Math.sin(phi);
    48	  const x0 = ex * cp - ey * sp, y0 = ex * sp + ey * cp - (susF + susR) / 2;
    49	  /* cuộn quanh đường chạm đất (trục X cục bộ): lean > 0 sang trái (−Z cục bộ) */
    50	  const y1 = y0 * Math.cos(lean), z1 = -y0 * Math.sin(lean);
    51	  /* dốc quanh Z, rồi yaw quanh Y */
    52	  const cq = Math.cos(p), sq = Math.sin(p), x2 = x0 * cq - y1 * sq, y2 = x0 * sq + y1 * cq;
    53	  const cy = Math.cos(yaw), sy = Math.sin(yaw);
    54	  out.x = fin(s.x) + x2 * cy + z1 * sy;
    55	  out.y = fin(s.y) + y2 + fin(c.bob);
    56	  out.z = fin(s.z) - x2 * sy + z1 * cy;
    57	  out.yaw = yaw + fin(c.yaw);
    58	  out.pitch = p + C1.pitchK * phi + C1.tilt + fin(c.pitch);
    59	  out.roll = fin(c.roll);
    60	}
    61	
    62	/* Lò xo bậc hai một kênh, Euler ẩn (ổn định với mọi h): trả vận tốc mới, người gọi cộng vị trí */
    63	const spr = (x: number, v: number, t: number, h: number): number => (v + h * W * W * (t - x)) / (1 + 2 * C1.damp * W * h + W * W * h * h);
    64	
    65	/* Một khung: trộn góc nhìn, góc nhìn quanh tự về, lò xo cuộn / nhún / dồn. motion 0..1 nhân nhún và dồn */
    66	export function bkCamStep(c: BkCam, s: BkState, dt: number, motion: number): void {
    67	  const d = dt > 0 && Number.isFinite(dt) ? dt : 0;
    68	  if (!(d > 0)) return;
    69	  const tgt = c.view === 3 ? 1 : 0;
    70	  c.mix = c.mix < tgt ? Math.min(tgt, c.mix + d / C1.mixS) : Math.max(tgt, c.mix - d / C1.mixS);
    71	  c.idle += d;
    72	  if (c.idle > C1.returnAfter) { const k = Math.exp(-C1.returnRate * d); c.yaw *= k; c.pitch *= k; }
    73	  const m = clamp(fin(motion), 0, 1);
    74	  const tRoll = (C1.rollK + (C1.roll3K - C1.rollK) * c.mix) * clamp(fin(s.lean), -LEAN_MAX, LEAN_MAX);
    75	  const tBob = m * clamp(-C1.bobK * (fin(s.susF) + fin(s.susR)) / 2, -C1.bobMax, C1.bobMax);
    76	  const tSurge = m * C1.surgeMax * clamp(-fin(s.acc) / HARD, -1, 1);   // phanh (acc < 0) ⇒ dồn trước; tăng tốc ⇒ lùi
    77	  const hT = Math.min(d, C1.dtMax), n = Math.ceil(hT * 120), h = hT / n;
    78	  for (let i = 0; i < n; i++) {
    79	    c.rollV = spr(c.roll, c.rollV, tRoll, h); c.roll += h * c.rollV;
    80	    c.bobV = spr(c.bob, c.bobV, tBob, h); c.bob += h * c.bobV;
    81	    c.surgeV = spr(c.surge, c.surgeV, tSurge, h); c.surge += h * c.surgeV;
    82	  }
    83	  c.roll = clamp(c.roll, -LEAN_MAX, LEAN_MAX);
    84	  if (m === 0) { c.bob = 0; c.bobV = 0; c.surge = 0; c.surgeV = 0; }
    85	  else { c.bob = clamp(c.bob, -C1.bobMax, C1.bobMax); c.surge = clamp(c.surge, -C1.surgeMax, C1.surgeMax); }
    86	}
    87	
    88	const _eye: BkEye = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, roll: 0 };
    89	const _e = new THREE.Euler(0, 0, 0, 'YXZ'), _q1 = new THREE.Quaternion(), _q3 = new THREE.Quaternion(), _qr = new THREE.Quaternion(), _p1 = new THREE.Vector3();
    90	const AZ = new THREE.Vector3(0, 0, 1);
    91	
    92	/* Đặt camera: trộn thứ nhất ↔ thứ ba theo smoothstep(c.mix); đặt fov + near; trả true khi fov / near đổi (người gọi onResize) */
    93	export function bkCamPlace(camera: THREE.PerspectiveCamera, s: BkState, c: BkCam, net: DrNet, dt: number, snap?: boolean): boolean {
    94	  const t = clamp(fin(c.mix), 0, 1), m = t * t * (3 - 2 * t);
    95	  /* góc thứ ba (luôn chạy để trạng thái trễ sẵn), cuộn thêm quanh trục nhìn */
    96	  drCamPlace(camera, s, c3, net, dt, snap, K3);
    97	  _q3.copy(camera.quaternion).multiply(_qr.setFromAxisAngle(AZ, fin(c.roll)));
    98	  /* góc thứ nhất: camera nhìn −Z cục bộ; yaw xe 0 = mũi +X ⇒ quay quanh Y thêm −π/2 */
    99	  bkCamEye(s, c, _eye);
   100	  _e.set(_eye.pitch, _eye.yaw - Math.PI / 2, _eye.roll, 'YXZ');
   101	  _q1.setFromEuler(_e);
   102	  _p1.set(_eye.x, _eye.y, _eye.z);
   103	  if (m >= 1) camera.quaternion.copy(_q3);
   104	  else if (m <= 0) { camera.position.copy(_p1); camera.quaternion.copy(_q1); }
   105	  else { camera.position.lerpVectors(_p1, camera.position, m); camera.quaternion.slerpQuaternions(_q1, _q3, m); }
   106	  const fov = C1.fov + (K3.fov - C1.fov) * m, near = C1.near + (K3.near - C1.near) * m;
   107	  if (camera.fov === fov && camera.near === near) return false;
   108	  camera.fov = fov; camera.near = near;
   109	  return true;
   110	}
   111	
   112	/* Kéo chuột / vuốt: góc thứ nhất nhìn quanh (sang phải ⇒ nhìn phải, xuống ⇒ nhìn xuống, kẹp), góc thứ ba quay quanh xe như ô tô */
   113	export function bkCamDrag(c: BkCam, dx: number, dy: number): void {
   114	  if (c.view === 3) { drCamDrag(c3, dx, dy, K3); return; }
   115	  c.yaw = clamp(c.yaw - fin(dx) * C1.mouse, -C1.yawMax, C1.yawMax);
   116	  c.pitch = clamp(c.pitch - fin(dy) * C1.mouse, C1.pitchMin, C1.pitchMax);
   117	  c.idle = 0;
   118	}
     1	/* ===== Xe máy: camera góc thứ nhất + trộn thứ nhất ↔ thứ ba (src/explore/bike/camera.ts) =====
     2	   Mắt cao hơn mặt đường đúng tầm người ngồi trên yên mô hình này, cuộn theo 60 % độ nghiêng có lò xo, nhún / dồn tắt hẳn khi motion = 0,
     3	   dồn ≤ surgeMax khi phanh gấp, khung dài không văng, đổi góc nhìn trộn đơn điệu trong mixS, kéo nhìn quanh bị kẹp và tự về, fov / near theo trộn. */
     4	import { test } from 'node:test';
     5	import assert from 'node:assert/strict';
     6	import * as THREE from 'three';
     7	import { CONFIG } from '../../src/config.ts';
     8	import { drMakeNet, type DrPad } from '../../src/explore/drive/net.ts';
     9	import { bkCamCreate, bkCamEye, bkCamStep, bkCamPlace, bkCamDrag, bkCamSetEye } from '../../src/explore/bike/camera.ts';
    10	import type { BkState } from '../../src/explore/bike/motion.ts';
    11	
    12	const C1 = CONFIG.bike.cam1, K3 = CONFIG.bike.cam3, CVT = CONFIG.bike.cvt, DT = 1 / 60;
    13	const flatPad = (x0: number, x1: number, z0: number, z1: number, y = 2.6): DrPad => ({ id: 'a', kind: 'road', x0, x1, z0, z1, y: () => y });
    14	const state = (o: Partial<BkState> = {}): BkState => ({ x: 5, y: 2.6, z: -3, yaw: 0.7, pitch: 0, v: 0, steer: 0, wheel: 0, braking: false, evac: 0, slide: 1, touch: 0,
    15	  lean: 0, leanV: 0, susF: 0, susFV: 0, susR: 0, susRV: 0, rpm: CVT.idle, throttle: 0, brakeK: 0, acc: 0, sig: 0, sigYaw: 0, sigT: 0, stuck: 0, ...o });
    16	const eye = () => ({ x: 0, y: 0, z: 0, yaw: 0, pitch: 0, roll: 0 });
    17	const net = () => drMakeNet([flatPad(-100, 100, -100, 100)], []);
    18	
    19	test('xe thẳng đứng: mắt cao hơn mặt đường 1,55–1,80 m (yên 0,85 m của mô hình), ở trên xe, hướng theo xe', () => {
    20	  bkCamSetEye(null);
    21	  const s = state(), c = bkCamCreate(), o = eye();
    22	  bkCamEye(s, c, o);
    23	  assert.ok(o.y - s.y >= 1.55 && o.y - s.y <= 1.8, `cao ${o.y - s.y}`);
    24	  assert.ok(Math.hypot(o.x - s.x, o.z - s.z) < 0.6, 'trong thân xe');
    25	  assert.ok(Math.abs(o.yaw - s.yaw) < 1e-9 && Math.abs(o.roll) < 1e-9);
    26	  /* mắt đặt theo người lái (bkCamSetEye) thì dùng số đó (điểm nhìn lùi thêm cam1.back) */
    27	  bkCamSetEye({ fore: -0.3, up: 1.65 });
    28	  bkCamEye(state({ yaw: 0 }), c, o);
    29	  assert.ok(Math.abs(o.x - 5 + 0.3 + C1.back) < 1e-9 && Math.abs(o.y - 2.6 - 1.65) < 1e-9 && Math.abs(o.z + 3) < 1e-9, `${o.x}, ${o.y}, ${o.z}`);
    30	  bkCamSetEye(null);
    31	});
    32	
    33	test('lean = 0,5 giữ 2 s ⇒ roll ≈ 0,3 (60 %); mắt dời sang trái khi nghiêng trái', () => {
    34	  const s = state({ lean: 0.5, v: 10 }), c = bkCamCreate();
    35	  for (let i = 0; i < 120; i++) bkCamStep(c, s, DT, 1);
    36	  assert.ok(Math.abs(c.roll - 0.5 * C1.rollK) <= 0.03, `roll ${c.roll}`);
    37	  const o = eye(), up = eye();
    38	  bkCamEye(s, c, o); bkCamEye(state({ v: 10 }), c, up);
    39	  const left = { x: -Math.sin(s.yaw), z: -Math.cos(s.yaw) };   // −Z cục bộ của xe
    40	  assert.ok((o.x - up.x) * left.x + (o.z - up.z) * left.z > 0.5, 'mắt sang trái');
    41	  assert.ok(o.y < up.y, 'mắt thấp xuống');
    42	});
    43	
    44	test('motion = 0 ⇒ bob = surge = 0, roll vẫn có', () => {
    45	  const s = state({ lean: 0.3, v: 20, acc: -6, susF: 0.03, susR: -0.01 }), c = bkCamCreate();
    46	  for (let i = 0; i < 120; i++) { s.susF = 0.02 * Math.sin(i * 0.7); s.susR = 0.02 * Math.cos(i * 0.9); bkCamStep(c, s, DT, 0); }
    47	  assert.equal(c.bob, 0); assert.equal(c.surge, 0);
    48	  assert.ok(c.roll > 0.1, `roll ${c.roll}`);
    49	});
    50	
    51	test('phanh gấp ⇒ dồn trước, |surge| ≤ surgeMax; tăng tốc ⇒ lùi; nhún ≤ bobMax', () => {
    52	  const s = state({ v: 20, acc: -CONFIG.bike.perf.hardBrake * 1.5 }), c = bkCamCreate();
    53	  let mx = 0;
    54	  for (let i = 0; i < 180; i++) { bkCamStep(c, s, DT, 1); mx = Math.max(mx, Math.abs(c.surge)); }
    55	  assert.ok(mx <= C1.surgeMax + 1e-12, `surge ${mx}`);
    56	  assert.ok(c.surge > 0.02, `dồn trước ${c.surge}`);
    57	  s.acc = 3;
    58	  for (let i = 0; i < 180; i++) bkCamStep(c, s, DT, 1);
    59	  assert.ok(c.surge < 0, `lùi ${c.surge}`);
