    21	export interface BkCam { view: 1 | 3; mix: number; yaw: number; pitch: number; idle: number; roll: number; rollV: number; bob: number; bobV: number; surge: number; surgeV: number }   // view đích; mix 0 thứ nhất .. 1 thứ ba; yaw / pitch rad nhìn quanh (trái + / lên +); idle s từ lần kéo cuối; roll rad (trái +), bob m (lên +), surge m (trước +) và vận tốc của chúng
