// Tạm (không commit): đo góc tay nắm / ngực so với camera góc thứ nhất, chụp ảnh chỉnh tilt.
// node tests/_bk7-probe.mjs <ch> "tilt,back,near;tilt,back,near;..."
import { launch, openApp } from './lib.mjs';

const ch = Number(process.argv[2] || 0), combos = (process.argv[3] || '').split(';').filter(Boolean).map((c) => c.split(',').map(Number));
const browser = await launch();
const { page, errors } = await openApp(browser, 'http://localhost:5199/?explore=bike', { width: 960, height: 540,
  before: (p) => p.addInitScript((c) => localStorage.setItem('stChar', String(c)), ch) });
await page.waitForFunction(() => window.__app.bike.active() && window.__app.bike.model?.real && window.__app.bike.rider, null, { timeout: 240000, polling: 2000 });
for (const [tilt, back, near] of combos.length ? combos : [[NaN, NaN, NaN]]) {
  const out = await page.evaluate(([tilt, back, near]) => {
    const a = window.__app, b = a.bike, T = a.THREE;
    if (Number.isFinite(tilt)) b.cfg.cam1.tilt = tilt;
    if (Number.isFinite(back)) b.cfg.cam1.back = back;
    if (Number.isFinite(near)) b.cfg.cam1.near = near;
    a.dayNight.night = 0; a.dayNight.target = 0;
    b.placeAt(-150, 8.6, 0);
    const s = b.state; s.v = 8;
    b.step(1 / 60, { gas: 0.3, brake: 0, steer: 0, hard: false, grip: 1 });
    const cam = a.camera; cam.updateMatrixWorld();
    const inv = cam.matrixWorldInverse;
    const ang = (o) => { const p = new T.Vector3().setFromMatrixPosition(o.matrixWorld).applyMatrix4(inv); return [+(Math.atan2(p.y, -p.z) * 180 / Math.PI).toFixed(1), +(Math.atan2(p.x, -p.z) * 180 / Math.PI).toFixed(1), +(-p.z).toFixed(3)]; };
    const an = b.model.anchors, res = { camY: +(cam.position.y - s.y).toFixed(3), fov: cam.fov, near: cam.near, tilt: b.cfg.cam1.tilt, back: b.cfg.cam1.back };
    res.gripL = ang(an.gripL);
    const dep = (o) => { const g = o.geometry; g.computeBoundingBox(); const bb = g.boundingBox; let mn = 1e9; for (let i = 0; i < 8; i++) { const p = new T.Vector3(i & 1 ? bb.max.x : bb.min.x, i & 2 ? bb.max.y : bb.min.y, i & 4 ? bb.max.z : bb.min.z).applyMatrix4(o.matrixWorld).applyMatrix4(inv); mn = Math.min(mn, -p.z); } return +mn.toFixed(3); };
    res.meshes = {}; b.model.group.traverse((o) => { if (o.isMesh && /mirror|Dash|lamp_head/.test(o.material.name)) res.meshes[o.material.name] = dep(o); });
    res.horizonTop = +(0.5 - 0.5 * Math.tan(-(b.cfg.cam1.tilt)) / Math.tan(cam.fov * Math.PI / 360)).toFixed(3);
    return res;
  }, [tilt, back, near]);
  console.log(JSON.stringify(out));
  await page.waitForTimeout(5000);
  await page.screenshot({ path: `tests/screens/bike-fp-tilt-${ch ? 'f' : 'm'}_${tilt}_${back}_${near}.png` });
}
console.log('errors', errors);
await browser.close();

