// Tạm (không commit): đo góc tay nắm / ngực so với camera góc thứ nhất, chụp ảnh chỉnh tilt. node tests/_bk7-probe.mjs <ch> [tilt] [back]
import { launch, openApp } from './lib.mjs';

const ch = Number(process.argv[2] || 0), tilt = process.argv[3], back = process.argv[4], near = process.argv[5];
const browser = await launch();
const { page, errors } = await openApp(browser, 'http://localhost:5199/?explore=bike', { width: 960, height: 540,
  before: (p) => p.addInitScript((c) => localStorage.setItem('stChar', String(c)), ch) });
await page.waitForFunction(() => window.__app.bike.active() && window.__app.bike.model?.real && window.__app.bike.rider, null, { timeout: 240000, polling: 2000 });
const out = await page.evaluate(([tilt, back, near]) => {
  const a = window.__app, b = a.bike, T = a.THREE;
  if (tilt) b.cfg.cam1.tilt = Number(tilt);
  if (back) b.cfg.cam1.back = Number(back);
  if (near) b.cfg.cam1.near = Number(near);
  a.dayNight.night = 0; a.dayNight.target = 0;
  const s = b.state;
  s.v = 8;
  b.step(1 / 60, { gas: 0.3, brake: 0, steer: 0, hard: false, grip: 1 });
  const cam = a.camera; cam.updateMatrixWorld();
  const inv = cam.matrixWorldInverse;
  const ang = (o) => { const p = new T.Vector3().setFromMatrixPosition(o.matrixWorld).applyMatrix4(inv); return [+(Math.atan2(p.y, -p.z) * 180 / Math.PI).toFixed(1), +(Math.atan2(p.x, -p.z) * 180 / Math.PI).toFixed(1), +(-p.z).toFixed(3)]; };
  const an = b.model.anchors, r = b.rider.root, res = { cam: cam.position.toArray(), fov: cam.fov, tilt: b.cfg.cam1.tilt, back: b.cfg.cam1.back };
  res.gripL = ang(an.gripL); res.gripR = ang(an.gripR);
  const dep = (o) => { const g = o.geometry; g.computeBoundingBox(); const bb = g.boundingBox; let mn = 1e9, mx = -1e9; for (let i = 0; i < 8; i++) { const p = new T.Vector3(i & 1 ? bb.max.x : bb.min.x, i & 2 ? bb.max.y : bb.min.y, i & 4 ? bb.max.z : bb.min.z).applyMatrix4(o.matrixWorld).applyMatrix4(inv); mn = Math.min(mn, -p.z); mx = Math.max(mx, -p.z); } return [+mn.toFixed(3), +mx.toFixed(3)]; };
  res.meshes = {}; b.model.group.traverse((o) => { if (o.isMesh) res.meshes[o.name + ':' + (o.material.name || '')] = dep(o); });
  res.near = cam.near;
  for (const n of ['Bip01_L_Hand', 'Bip01_R_Hand', 'Bip01_L_Forearm', 'Bip01_Spine2', 'Bip01_Neck', 'Bip01_L_Clavicle', 'Bip01_R_Clavicle', 'Bip01_L_UpperArm', 'Bip01_R_UpperArm', 'Bip01_Spine1', 'Bip01_Head']) { const o = r.getObjectByName(n) || r.getObjectByName(n.replace(/_/g, ' ')); if (o) res[n] = ang(o); }
  return res;
}, [tilt, back, near]);
console.log(JSON.stringify(out));
await page.waitForTimeout(4000);
await page.screenshot({ path: `tests/screens/bike-fp-tilt-${ch ? 'f' : 'm'}${tilt ? '-' + tilt : ''}${back ? '-b' + back : ''}${near ? '-n' + near : ''}.png` });
console.log('errors', errors);
await browser.close();

