// Tạm (không commit): ảnh + lệnh vẽ Task 7 (đêm, mưa, dốc hầm ướt, góc nhìn thứ nhất). node tests/_bk7-fx.mjs <ch> [shots: all|tilt]
import { launch, openApp, frames } from './lib.mjs';

const ch = Number(process.argv[2] || 0), mode = process.argv[3] || 'all';
const browser = await launch();
const { page, errors } = await openApp(browser, 'http://localhost:5199/?explore=bike', { width: 960, height: 540,
  before: (p) => p.addInitScript((c) => localStorage.setItem('stChar', String(c)), ch) });
await page.waitForFunction(() => window.__app.bike.active() && window.__app.bike.model?.real && window.__app.bike.rider, null, { timeout: 240000, polling: 2000 });

/* đặt xe, đặt thời tiết + ngày đêm, lái 0,5 s ở v (bước 1/60) để bụi nước sinh ra; view 1 | 3 */
const setup = (o) => page.evaluate((o) => {
  const a = window.__app, b = a.bike, w = a.weather;
  a.dayNight.night = o.night; a.dayNight.target = o.night;
  w.setPreset(o.wx); w.setIntensity(1); Object.assign(w.state.current, w.state.target); w.state.wet = w.state.current.rain;
  b.setView(o.view); b.placeAt(o.x, o.z, o.yaw);
  b.cam.mix = o.view === 3 ? 1 : 0;
  const s = b.state;
  for (let i = 0; i < 30; i++) { s.v = o.v; b.step(1 / 60, { gas: 0.4, brake: 0, steer: 0, hard: false, grip: 1 }); }
  return { wet: a.weather.state.wet, night: a.shared.uNight.value, drawn: b.fx.drawn(), y: s.y, pitch: s.pitch };
}, o);
const keep = (v) => page.evaluate((v) => { const b = window.__app.bike, s = b.state; s.v = v; b.step(1 / 60, { gas: 0.4, brake: 0, steer: 0, hard: false, grip: 1 }); }, v);
const calls = async (v) => { const xs = []; for (let i = 0; i < 5; i++) { await keep(v); await frames(page, 1); xs.push(await page.evaluate(() => window.__app.renderer.info.render.calls)); } xs.sort((a, b) => a - b); return xs[2]; };
const shot = async (name, v) => { await keep(v); await page.waitForTimeout(4000); await keep(v); await frames(page, 1); await page.screenshot({ path: `tests/screens/${name}.png` }); };
const BR = { x: -150, z: 8.6, yaw: 0 };

if (mode === 'tilt') {
  await page.evaluate(() => { const a = window.__app; a.scene.traverse((o) => { if (o.isMesh && o.material === a.traffic.material) o.visible = false; }); });
  console.log(JSON.stringify(await setup({ ...BR, night: 0, wx: 'now', view: 1, v: 8 })));
  await shot(`bike-fp-tilt-${ch ? 'f' : 'm'}`, 8);
} else {
  /* lệnh vẽ: cùng chỗ, cùng góc thứ ba, xe tự động để nguyên */
  const res = {};
  for (const [k, o] of Object.entries({ day: { night: 0, wx: 'now' }, night: { night: 1, wx: 'now' }, rain: { night: 0, wx: 'rain' }, rainNight: { night: 1, wx: 'rain' } })) {
    for (const view of [3, 1]) { const st = await setup({ ...BR, ...o, view, v: 10 }); res[`${k}-v${view}`] = { calls: await calls(10), ...st.drawn, wet: +st.wet.toFixed(2) }; }
  }
  console.log('calls', JSON.stringify(res));
  await page.evaluate(() => { const a = window.__app; a.scene.traverse((o) => { if (o.isMesh && o.material === a.traffic.material) o.visible = false; }); });
  console.log(JSON.stringify(await setup({ ...BR, night: 1, wx: 'now', view: 1, v: 10 }))); await shot('bike-night-beam-fp', 10);
  console.log(JSON.stringify(await setup({ ...BR, night: 1, wx: 'now', view: 3, v: 10 }))); await shot('bike-night-beam', 10);
  console.log(JSON.stringify(await setup({ ...BR, night: 0, wx: 'rain', view: 3, v: 14 }))); await shot('bike-rain', 14);
  console.log(JSON.stringify(await setup({ ...BR, night: 1, wx: 'rain', view: 3, v: 14 }))); await shot('bike-rain-night', 14);
  const tun = { x: -640, z: -1700 + 9.5, yaw: 0 };
  console.log(JSON.stringify(await setup({ ...tun, night: 1, wx: 'rain', view: 3, v: 10 }))); await shot('bike-tunnel-ramp-wet', 10);
  console.log(JSON.stringify(await setup({ ...tun, night: 0, wx: 'rain', view: 3, v: 10 }))); await shot('bike-tunnel-ramp-wet-day', 10);
  /* trong đoạn kín: khô, không bụi nước */
  console.log('covered', JSON.stringify(await setup({ x: -420, z: -1700 + 9.5, yaw: 0, night: 0, wx: 'rain', view: 3, v: 10 })));
  console.log('programs', await page.evaluate(() => window.__app.renderer.info.programs.length));
}
console.log('errors', errors);
await browser.close();

